    46  static void view_sam(htsFile *in) {
    47      if (!in) {
    48          return;
    49      }
    50      samFile *out = sam_open("/dev/null", "w");
    51      if (!out) {
    52          abort();
    53      }
    54      sam_hdr_t *hdr = sam_hdr_read(in);
    55      if (hdr == NULL) {
    56          hts_close_or_abort(out);
    57          return;
    58      }
    59
    60      // This will force the header to be parsed.
    61      (void) sam_hdr_count_lines(hdr, "SQ");
    62
    63      if (sam_hdr_write(out, hdr) != 0) {
    64          sam_hdr_destroy(hdr);
    65          hts_close_or_abort(out);
    66          return;
    67      }
    68      bam1_t *b = bam_init1();
    69      if (b == NULL) {
    70          sam_hdr_destroy(hdr);
    71          hts_close_or_abort(out);
    72          return;
    73      }
    74      while (sam_read1(in, hdr, b) >= 0) {
    75          if (sam_write1(out, hdr, b) < 0) {
    76              break;
    77          }
    78      }
    79      bam_destroy1(b);
    80
    81      sam_hdr_destroy(hdr);
    82      hts_close_or_abort(out);
    83  }
