  4529  cram_file_def *cram_read_file_def(cram_fd *fd) {
  4530      cram_file_def *def = malloc(sizeof(*def));
  4531      if (!def)
  4532          return NULL;
  4533
  4534      if (26 != hread(fd->fp, &def->magic[0], 26)) {
  4535          free(def);
  4536          return NULL;
  4537      }
  4538
  4539      if (memcmp(def->magic, "CRAM", 4) != 0) {
  4540          free(def);
  4541          return NULL;
