  2842  static void mkdir_prefix(char *path, int mode) {
  2843      char *cp = strrchr(path, '/');
  2844      if (!cp)
  2845          return;
  2846
  2847      *cp = 0;
  2848      if (is_directory(path)) {
  2849          *cp = '/';
  2850          return;
  2851      }
  2852
  2853      if (mkdir(path, mode) == 0) {
  2854          chmod(path, mode);
  2855          *cp = '/';
  2856          return;
  2857      }
  2858
  2859      mkdir_prefix(path, mode);
  2860      mkdir(path, mode);
  2861      chmod(path, mode);
  2862      *cp = '/';
  2863  }
